    "discipline": "Other",
    "subject": "Thermodynamics and Heat Transfer",
    "chapter": "Basic Cycles",
    "topic": "Diesel Cycle",
    "subtopic": "Overview",
    "content_html": "<div class= \"container-fluid\">\r\n  <div class= \"row align-items-start\">\r\n   <div class=\"col col-lg-8\">\r\n   <ul>\r\n<li>Process 1: Suction stroke</li>\r\n<li>Process 2: Compression stroke</li>\r\n<li>Process 3: Power stroke</li>\r\n<li>Process 4: Exhaust stroke</li>\r\n</ul>\r\n    </div>\r\n    <div class=\"col\">\r\n<center><p><img src=\"https://upload.wikimedia.org/wikipedia/commons/1/1b/Diesel_obieg.png\" style=\"max-width: 50vh;\"></p><br/>\r\n<small><small><a href=\"https://commons.wikimedia.org/wiki/File:Diesel_obieg.png\">Aprzekwas</a>, <a href=\"https://creativecommons.org/licenses/by-sa/3.0\">CC BY-SA 3.0</a>, via Wikimedia Commons</small></small></center><br/>\r\n    </div>\r\n  </div>\r\n</div>",
    "important": "",
